"""Tables, field conversion, column naming, names, keywords, literals, syntax."""

import unittest

import minisql

from tests.helpers import MiniSQLTestCase


class TestResultShape(MiniSQLTestCase):
    def test_run_returns_columns_list_and_rows_list_of_tuples(self):
        r = self.run_sql("SELECT ID, Name FROM products")
        self.assertIsInstance(r.columns, list)
        self.assertIsInstance(r.rows, list)
        self.assertEqual(len(r.rows), 5)
        for row in r.rows:
            self.assertIsInstance(row, tuple)
            self.assertEqual(len(row), 2)

    def test_query_error_is_exception(self):
        self.assertTrue(issubclass(minisql.QueryError, Exception))


class TestTables(MiniSQLTestCase):
    def test_select_star_columns_in_file_order(self):
        self.assertEqual(
            self.columns("SELECT * FROM products"),
            ["ID", "Name", "Price", "Qty", "Category", "Unit Price"])

    def test_select_star_rows_in_file_order_with_conversion(self):
        self.assertRows("SELECT * FROM products", [
            (1, "widget", 25, 3, "tools", 8.5),
            (2, "gadget", 12.5, None, "toys", None),
            (3, "gizmo", None, 5, "tools", 1.0),
            (4, "doohickey", 7, 10, None, 0.5),
            (5, "Widget", -3, 0, "toys", -2.25),
        ])

    def test_empty_table_select_star(self):
        r = self.run_sql("SELECT * FROM empty")
        self.assertEqual(r.columns, ["x", "y"])
        self.assertEqual(r.rows, [])

    def test_empty_table_select_column(self):
        r = self.run_sql("SELECT y FROM empty")
        self.assertEqual(r.columns, ["y"])
        self.assertEqual(r.rows, [])

    def test_missing_table_is_error(self):
        self.assertQueryError("SELECT * FROM nosuchtable")

    def test_unknown_column_is_error(self):
        self.assertQueryError("SELECT nope FROM products")

    def test_unknown_column_in_where_is_error(self):
        self.assertQueryError("SELECT ID FROM products WHERE nope = 1")

    def test_unknown_column_in_order_by_is_error(self):
        self.assertQueryError("SELECT ID FROM products ORDER BY nope")

    def test_unknown_column_on_empty_table_is_error(self):
        self.assertQueryError("SELECT nope FROM empty")

    def test_unknown_column_in_where_on_empty_table_is_error(self):
        self.assertQueryError("SELECT x FROM empty WHERE nope = 1")


class TestFieldConversion(MiniSQLTestCase):
    def v(self, id_):
        rows = self.rows("SELECT v FROM types WHERE id = %d" % id_)
        self.assertEqual(len(rows), 1)
        return rows[0][0]

    def assertField(self, id_, expected):
        v = self.v(id_)
        self.assertEqual((type(v).__name__, v),
                         (type(expected).__name__, expected))

    def test_integer(self):
        self.assertField(1, 42)

    def test_negative_integer(self):
        self.assertField(2, -3)

    def test_integer_with_leading_zeros(self):
        self.assertField(12, 7)

    def test_decimal_trailing_dot(self):
        self.assertField(3, 1.0)

    def test_decimal_leading_dot(self):
        self.assertField(4, 0.5)

    def test_negative_decimal_leading_dot(self):
        self.assertField(5, -0.5)

    def test_negative_decimal(self):
        self.assertField(18, -0.25)

    def test_exponent_stays_string(self):
        self.assertField(6, "1e5")

    def test_digits_then_letters_stay_string(self):
        self.assertField(7, "12abc")

    def test_empty_is_null(self):
        self.assertIsNone(self.v(8))

    def test_plain_string(self):
        self.assertField(9, "hello world")

    def test_plus_sign_stays_string(self):
        self.assertField(10, "+5")

    def test_two_dots_stay_string(self):
        self.assertField(11, "1.2.3")

    def test_lone_minus_stays_string(self):
        self.assertField(13, "-")

    def test_lone_dot_stays_string(self):
        self.assertField(14, ".")

    # Interpretation: the patterns must match the whole field, and the field
    # is not stripped, so " 5" is a string.
    def test_leading_space_stays_string(self):
        self.assertField(15, " 5")

    def test_true_text_is_string_not_boolean(self):
        self.assertField(16, "true")

    def test_null_text_is_string_not_null(self):
        self.assertField(17, "NULL")


class TestColumnNaming(MiniSQLTestCase):
    def test_plain_column_uses_header_spelling(self):
        self.assertEqual(self.columns("SELECT name, PRICE, id FROM products"),
                         ["Name", "Price", "ID"])

    def test_quoted_column_with_space(self):
        r = self.run_sql('SELECT "Unit Price" FROM products WHERE ID = 1')
        self.assertEqual(r.columns, ["Unit Price"])
        self.assertEqual(r.rows, [(8.5,)])

    def test_quoted_column_matched_case_insensitively(self):
        r = self.run_sql('SELECT "unit PRICE" FROM products WHERE ID = 1')
        self.assertEqual(r.columns, ["Unit Price"])
        self.assertEqual(r.rows, [(8.5,)])

    def test_alias_with_as(self):
        self.assertEqual(self.columns("SELECT Name AS n FROM products"), ["n"])

    def test_alias_without_as(self):
        self.assertEqual(self.columns("SELECT Name n FROM products"), ["n"])

    def test_alias_keeps_case(self):
        self.assertEqual(self.columns("SELECT Name AS MyName FROM products"),
                         ["MyName"])

    def test_quoted_alias(self):
        self.assertEqual(
            self.columns('SELECT Name AS "my name" FROM products'),
            ["my name"])

    def test_quoted_alias_with_escaped_quote(self):
        self.assertEqual(
            self.columns('SELECT Name AS "a""b" FROM products'), ['a"b'])

    def test_alias_on_expression(self):
        r = self.run_sql("SELECT Price * 2 AS double FROM products WHERE ID = 1")
        self.assertEqual(r.columns, ["double"])
        self.assertEqual(r.rows, [(50,)])

    def test_expression_text_as_written(self):
        self.assertEqual(self.columns("SELECT price * 2 FROM products"),
                         ["price * 2"])

    def test_expression_text_without_spaces(self):
        self.assertEqual(self.columns("SELECT price*2 FROM products"),
                         ["price*2"])

    # Interpretation: "exactly as written" preserves internal whitespace.
    def test_expression_text_preserves_internal_spacing(self):
        self.assertEqual(self.columns("SELECT price  *   2 FROM products"),
                         ["price  *   2"])

    def test_count_star_name(self):
        self.assertEqual(self.columns("SELECT COUNT(*) FROM products"),
                         ["COUNT(*)"])

    def test_count_star_name_keeps_case(self):
        self.assertEqual(self.columns("SELECT count(*) FROM products"),
                         ["count(*)"])

    def test_function_call_name(self):
        self.assertEqual(self.columns("SELECT LOWER(Name) FROM products"),
                         ["LOWER(Name)"])

    def test_literal_expression_names(self):
        self.assertEqual(
            self.columns("SELECT 1 + 1, 'a' || 'b' FROM one"),
            ["1 + 1", "'a' || 'b'"])

    def test_multiple_columns_mixed(self):
        self.assertEqual(
            self.columns('SELECT id, "unit price" AS up, Qty + 1 FROM products'),
            ["ID", "up", "Qty + 1"])


class TestNames(MiniSQLTestCase):
    def test_quoted_name_with_escaped_quote(self):
        r = self.run_sql('SELECT "say ""hi""" FROM kw')
        self.assertEqual(r.columns, ['say "hi"'])
        self.assertEqual(r.rows, [(3,)])

    def test_quoted_keyword_column(self):
        r = self.run_sql('SELECT "order", "select" FROM kw')
        self.assertEqual(r.columns, ["order", "select"])
        self.assertEqual(r.rows, [(1, 2)])

    def test_unquoted_keyword_column_is_error(self):
        self.assertQueryError("SELECT order FROM kw")

    def test_unquoted_keyword_column_select_is_error(self):
        self.assertQueryError("SELECT select FROM kw")

    def test_keyword_as_unquoted_alias_is_error(self):
        self.assertQueryError("SELECT ID AS from FROM products")

    def test_keyword_as_unquoted_alias_lowercase_is_error(self):
        self.assertQueryError("SELECT ID AS where FROM products")

    def test_keyword_quoted_alias_ok(self):
        self.assertEqual(self.columns('SELECT ID AS "from" FROM products'),
                         ["from"])

    def test_underscore_names(self):
        r = self.run_sql("SELECT ID AS _x1 FROM products WHERE ID = 1")
        self.assertEqual(r.columns, ["_x1"])

    def test_column_names_case_insensitive_everywhere(self):
        self.assertRows(
            "SELECT nAmE FROM products WHERE qTY > 4 ORDER BY pRiCe",
            [("doohickey",), ("gizmo",)][::-1][::-1] and
            [("gizmo",), ("doohickey",)])


class TestKeywordsCaseInsensitive(MiniSQLTestCase):
    def test_lowercase_keywords(self):
        self.assertRows(
            "select distinct category from products where qty is not null "
            "and category is not null order by category desc limit 1 offset 0",
            [("tools",)])

    def test_mixed_case_keywords(self):
        self.assertRows(
            "sElEcT Name aS n FrOm products wHeRe ID BeTwEeN 2 aNd 3 "
            "AnD Name NoT LiKe 'x%' oRdEr By n DeSc",
            [("gizmo",), ("gadget",)])

    def test_lowercase_literals(self):
        self.assertIs(self.value("true"), True)
        self.assertIs(self.value("False"), False)
        self.assertIsNone(self.value("null"))

    def test_lowercase_in_and_group_by_having(self):
        self.assertRows(
            "select region, count(*) from sales where region not in ('x') "
            "group by region having count(*) > 1 order by 1 asc",
            [("east", 2), ("west", 2)])

    def test_function_names_case_insensitive(self):
        self.assertValue("lower('AB')", "ab")
        self.assertValue("Upper('ab')", "AB")
        self.assertValue("cOaLeScE(NULL, 3)", 3)


class TestLiterals(MiniSQLTestCase):
    def test_integer_literal(self):
        self.assertValue("42", 42)

    def test_decimal_literal(self):
        self.assertValue("2.5", 2.5)

    def test_decimal_leading_dot_literal(self):
        self.assertValue(".5", 0.5)

    def test_string_literal(self):
        self.assertValue("'hello'", "hello")

    def test_string_literal_escaped_quote(self):
        self.assertValue("'it''s'", "it's")

    def test_empty_string_literal(self):
        self.assertValue("''", "")

    def test_string_literal_keeps_case_and_spaces(self):
        self.assertValue("'A b  C'", "A b  C")

    def test_null_literal(self):
        self.assertNull("NULL")

    def test_true_false_literals(self):
        self.assertIs(self.value("TRUE"), True)
        self.assertIs(self.value("FALSE"), False)

    def test_literal_per_row(self):
        self.assertRows("SELECT 7 FROM products", [(7,)] * 5)


class TestStatementForm(MiniSQLTestCase):
    def test_trailing_semicolon(self):
        self.assertRows("SELECT ID FROM products WHERE ID = 1;", [(1,)])

    def test_trailing_semicolon_after_limit(self):
        self.assertRows("SELECT ID FROM products LIMIT 1;", [(1,)])

    def test_whitespace_and_newlines(self):
        self.assertRows("  SELECT\n\tID\nFROM   products\nWHERE ID=2  ",
                        [(2,)])


class TestSyntaxErrors(MiniSQLTestCase):
    BAD = [
        "",
        "SELECT",
        "SELECT FROM products",
        "SELECT ID products",
        "SELECT ID FROM",
        "SELECT ID FROM products WHERE",
        "SELECT ID, FROM products",
        "SELECT ID,, Name FROM products",
        "SELECT 1 + FROM products",
        "SELECT (1 FROM products",
        "SELECT 1) FROM products",
        "SELECT 'abc FROM products",
        'SELECT "abc FROM products',
        "SELECT ID FROM products extra stuff",
        "SELECT ID FROM products ORDER ID",
        "SELECT ID FROM products GROUP ID",
        "SELECT ID FROM products LIMIT",
        "SELECT ID FROM products LIMIT x",
        "SELECT ID FROM products LIMIT 1.5",
        "SELECT ID FROM products OFFSET 1",
        "SELECT ID FROM products LIMIT 1 OFFSET",
        "SELECT ID FROM products;;",
        "SELECT ID FROM products; SELECT ID FROM products",
        "SELECT *, ID FROM products",
        "SELECT ID, * FROM products",
        "SELECT ID FROM products WHERE ID IN ()",
        "SELECT ID FROM products WHERE ID IN 1, 2",
        "SELECT ID FROM products WHERE ID BETWEEN 1",
        "SELECT ID FROM products WHERE ID IS 1",
        "SELECT ID FROM products WHERE ID = = 1",
        "SELECT ID FROM products ORDER BY ID LIMIT 1 WHERE ID = 1",
        "SELECT ID FROM products WHERE ID = 1 WHERE ID = 2",
        "SELECT LOWER(Name FROM products",
        "SELECT ID AS FROM products",
        "SELECT ID FROM products WHERE ID @ 1",
        "FROM products SELECT ID",
        "SELECT DISTINCT FROM products",
    ]

    def test_syntax_errors(self):
        for sql in self.BAD:
            with self.subTest(sql=sql):
                self.assertQueryError(sql)


if __name__ == "__main__":
    unittest.main()

