from tests.helpers import MiniSQLTestCase


class TestResultShape(MiniSQLTestCase):
    def test_run_returns_columns_list_and_rows_list_of_tuples(self):
        r = self.run_sql("SELECT ID, Name FROM products")
        self.assertIsInstance(r.columns, list)
        self.assertIsInstance(r.rows, list)
        self.assertEqual(len(r.rows), 5)
        for row in r.rows:
            self.assertIsInstance(row, tuple)
