class TestFieldConversion(MiniSQLTestCase):
    def v(self, id_):
        rows = self.rows("SELECT v FROM types WHERE id = %d" % id_)
        self.assertEqual(len(rows), 1)
        return rows[0][0]

    def assertField(self, id_, expected):
        v = self.v(id_)
        self.assertEqual((type(v).__name__, v),
                         (type(expected).__name__, expected))

    def test_integer(self):
        self.assertField(1, 42)

    def test_negative_integer(self):
        self.assertField(2, -3)

    def test_integer_with_leading_zeros(self):
        self.assertField(12, 7)

    def test_decimal_trailing_dot(self):
        self.assertField(3, 1.0)

    def test_decimal_leading_dot(self):
        self.assertField(4, 0.5)

    def test_negative_decimal_leading_dot(self):
        self.assertField(5, -0.5)

    def test_negative_decimal(self):
        self.assertField(18, -0.25)

    def test_exponent_stays_string(self):
        self.assertField(6, "1e5")

    def test_digits_then_letters_stay_string(self):
        self.assertField(7, "12abc")

    def test_empty_is_null(self):
        self.assertIsNone(self.v(8))

    def test_plain_string(self):
        self.assertField(9, "hello world")

    def test_plus_sign_stays_string(self):
        self.assertField(10, "+5")

    def test_two_dots_stay_string(self):
        self.assertField(11, "1.2.3")

    def test_lone_minus_stays_string(self):
        self.assertField(13, "-")

    def test_lone_dot_stays_string(self):
        self.assertField(14, ".")

    # Interpretation: the patterns must match the whole field, and the field
    # is not stripped, so " 5" is a string.
    def test_leading_space_stays_string(self):
        self.assertField(15, " 5")

    def test_true_text_is_string_not_boolean(self):
        self.assertField(16, "true")

    def test_null_text_is_string_not_null(self):
        self.assertField(17, "NULL")


