"""Expression semantics: precedence, NULLs, arithmetic, comparisons, functions."""

import unittest

from tests.helpers import MiniSQLTestCase


class TestPrecedence(MiniSQLTestCase):
    def test_mul_before_add(self):
        self.assertValue("1 + 2 * 3", 7)

    def test_parentheses(self):
        self.assertValue("(1 + 2) * 3", 9)

    def test_subtraction_left_to_right(self):
        self.assertValue("10 - 2 - 3", 5)

    def test_division_left_to_right(self):
        self.assertValue("8 / 2 / 2", 2.0)

    def test_mul_div_left_to_right(self):
        self.assertValue("6 / 3 * 2", 4.0)

    def test_concat_at_additive_level_left_to_right(self):
        # (1 + 2) || 3
        self.assertValue("1 + 2 || 3", "33")

    def test_concat_then_add_is_string_arithmetic_error(self):
        # ('a' || 1) + 2 -> arithmetic on a string
        self.assertExprError("'a' || 1 + 2")

    def test_mul_binds_tighter_than_concat(self):
        self.assertValue("'a' || 2 * 3", "a6")

    def test_unary_minus_binds_tighter_than_concat(self):
        # (-1) || 'x'; if unary minus were lower it would negate a string.
        self.assertValue("-1 || 'x'", "-1x")

    def test_unary_minus_binds_tighter_than_mul(self):
        self.assertValue("-2 * 3", -6)
        self.assertValue("2 * -3", -6)

    def test_double_unary_minus(self):
        self.assertValue("- -4", 4)

    def test_unary_minus_on_column(self):
        self.assertRows("SELECT -Price FROM products WHERE ID IN (1, 5)",
                        [(-25,), (3,)])

    def test_comparison_below_additive(self):
        self.assertIs(self.value("1 + 1 = 2"), True)
        self.assertIs(self.value("2 * 3 > 5"), True)

    def test_not_below_comparison(self):
        # NOT (1 = 2), not (NOT 1) = 2
        self.assertIs(self.value("NOT 1 = 2"), True)

    def test_not_below_comparison_in_where(self):
        self.assertRows("SELECT ID FROM products WHERE NOT Qty > 2", [(5,)])

    def test_and_before_or(self):
        self.assertIs(self.value("TRUE OR TRUE AND FALSE"), True)
        self.assertIs(self.value("FALSE AND FALSE OR TRUE"), True)

    def test_not_before_and(self):
        # (NOT FALSE) AND FALSE
        self.assertIs(self.value("NOT FALSE AND FALSE"), False)

    def test_not_before_or(self):
        # (NOT TRUE) OR TRUE
        self.assertIs(self.value("NOT TRUE OR TRUE"), True)

    def test_double_not(self):
        self.assertIs(self.value("NOT NOT TRUE"), True)

    def test_between_operands_are_additive(self):
        self.assertIs(self.value("3 BETWEEN 1 + 1 AND 2 + 2"), True)

    def test_between_followed_by_and(self):
        self.assertRows(
            "SELECT ID FROM products WHERE ID BETWEEN 2 AND 4 AND Qty > 4",
            [(3,), (4,)])

    def test_between_followed_by_or(self):
        self.assertRows(
            "SELECT ID FROM products WHERE ID BETWEEN 2 AND 3 OR ID = 5",
            [(2,), (3,), (5,)])


class TestNull(MiniSQLTestCase):
    def test_arithmetic_with_null(self):
        for expr in ["1 + NULL", "NULL - 1", "2 * NULL", "NULL / 2",
                     "-NULL", "1.5 + NULL"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_concat_with_null(self):
        self.assertNull("'a' || NULL")
        self.assertNull("NULL || 'a'")

    def test_comparison_with_null(self):
        for expr in ["NULL = NULL", "1 = NULL", "NULL <> 1", "NULL != 1",
                     "1 < NULL", "NULL >= 1", "'a' > NULL"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_not_null(self):
        self.assertNull("NOT NULL")

    def test_like_with_null(self):
        self.assertNull("NULL LIKE 'a'")
        self.assertNull("'a' LIKE NULL")

    def test_scalar_functions_with_null(self):
        for expr in ["LOWER(NULL)", "UPPER(NULL)", "LENGTH(NULL)",
                     "ABS(NULL)", "ROUND(NULL)", "ROUND(NULL, 1)",
                     "ROUND(1.5, NULL)"]:
            with self.subTest(expr=expr):
                self.assertNull(expr)

    def test_three_valued_and(self):
        self.assertIs(self.value("FALSE AND NULL"), False)
        self.assertIs(self.value("NULL AND FALSE"), False)
        self.assertNull("TRUE AND NULL")
        self.assertNull("NULL AND TRUE")
        self.assertNull("NULL AND NULL")

    def test_three_valued_or(self):
        self.assertIs(self.value("TRUE OR NULL"), True)
        self.assertIs(self.value("NULL OR TRUE"), True)
        self.assertNull("FALSE OR NULL")
        self.assertNull("NULL OR FALSE")
        self.assertNull("NULL OR NULL")

    def test_is_null_never_null(self):
        self.assertIs(self.value("NULL IS NULL"), True)
        self.assertIs(self.value("1 IS NULL"), False)
        self.assertIs(self.value("NULL IS NOT NULL"), False)
        self.assertIs(self.value("'' IS NOT NULL"), True)
        self.assertIs(self.value("(1 + NULL) IS NULL"), True)

    def test_is_null_on_column(self):
        self.assertRows(
            "SELECT ID, Qty IS NULL, Qty IS NOT NULL FROM products "
            "WHERE ID <= 2",
            [(1, False, True), (2, True, False)])

    def test_where_keeps_only_true(self):
        # Qty is NULL for ID 2: both the condition and its negation are NULL.
        self.assertRows("SELECT ID FROM products WHERE Qty > 2",
                        [(1,), (3,), (4,)])
        self.assertRows("SELECT ID FROM products WHERE NOT (Qty > 2)",
                        [(5,)])

    def test_where_null_literal_keeps_nothing(self):
        self.assertRows("SELECT ID FROM products WHERE NULL", [])

    def test_where_false_keeps_nothing(self):
        self.assertRows("SELECT ID FROM products WHERE FALSE", [])

    def test_where_is_null(self):
        self.assertRows("SELECT Name FROM products WHERE Category IS NULL",
                        [("doohickey",)])

    def test_where_three_valued_or(self):
        # Qty > 100 is NULL for ID 2, but ID = 2 is TRUE.
        self.assertRows(
            "SELECT ID FROM products WHERE Qty > 100 OR ID = 2", [(2,)])


class TestArithmetic(MiniSQLTestCase):
