class TestLike(MiniSQLTestCase):
    def check(self, cases):
        for expr, expected in cases.items():
            with self.subTest(expr=expr):
                self.assertIs(self.value(expr), expected)

    def test_percent(self):
        self.check({
            "'abc' LIKE 'a%'": True,
            "'abc' LIKE '%c'": True,
            "'abc' LIKE '%b%'": True,
            "'abc' LIKE 'a%c'": True,
            "'ac' LIKE 'a%c'": True,
            "'abc' LIKE '%'": True,
            "'' LIKE '%'": True,
            "'abc' LIKE 'b%'": False,
            "'abc' LIKE '%%'": True,
        })

    def test_underscore(self):
        self.check({
            "'abc' LIKE 'a_c'": True,
            "'abc' LIKE '___'": True,
            "'abc' LIKE '__'": False,
            "'abc' LIKE 'a_'": False,
            "'ac' LIKE 'a_c'": False,
            "'abc' LIKE '_%'": True,
            "'' LIKE '_'": False,
        })

    def test_whole_string_match(self):
        self.check({
            "'abc' LIKE 'b'": False,
            "'abc' LIKE 'ab'": False,
            "'abc' LIKE 'bc'": False,
            "'abc' LIKE 'abc'": True,
            "'abcabc' LIKE 'abc'": False,
        })

    def test_case_sensitive(self):
        self.check({
            "'abc' LIKE 'A%'": False,
            "'ABC' LIKE 'abc'": False,
            "'ABC' LIKE 'A_C'": True,
        })

    def test_regex_metacharacters_are_literal(self):
        self.check({
            "'a.c' LIKE 'a.c'": True,
            "'abc' LIKE 'a.c'": False,
            "'a+b' LIKE 'a+b'": True,
            "'aab' LIKE 'a+b'": False,
            "'a*' LIKE 'a*'": True,
            "'aaa' LIKE 'a*'": False,
            "'(x)' LIKE '(x)'": True,
            "'[ab]' LIKE '[ab]'": True,
            "'a' LIKE '[ab]'": False,
            "'a?' LIKE 'a?'": True,
            "'a' LIKE 'a?'": False,
            "'^a$' LIKE '^a$'": True,
            "'a' LIKE '^a$'": False,
            "'a|b' LIKE 'a|b'": True,
            "'a' LIKE 'a|b'": False,
            "'a\\b' LIKE 'a\\b'": True,
            "'{1}' LIKE '{1}'": True,
            "'x.y.z' LIKE '%.%'": True,
            "'xyz' LIKE '%.%'": False,
        })

    def test_not_like(self):
        self.check({
            "'abc' NOT LIKE 'a%'": False,
            "'abc' NOT LIKE 'x%'": True,
        })

    def test_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name LIKE 'w%'",
                        [(1,)])
        self.assertRows("SELECT ID FROM products WHERE Name LIKE '%dg%'",
                        [(2,)])

    def test_not_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name NOT LIKE '%g%'",
                        [(1,), (4,), (5,)])

    def test_like_pattern_expression(self):
        self.assertIs(self.value("'abc' LIKE 'a' || '%'"), True)


