            "SELECT ID FROM products WHERE Category IN ('toys', 'x')",
            [(2,), (5,)])

    def test_not_in_where_excludes_nulls(self):
        # Category is NULL for ID 4, so NOT IN is NULL there.
        self.assertRows(
            "SELECT ID FROM products WHERE Category NOT IN ('toys')",
            [(1,), (3,)])


class TestBetween(MiniSQLTestCase):
    def test_between_inside(self):
        self.assertIs(self.value("5 BETWEEN 1 AND 10"), True)

    def test_between_inclusive(self):
        self.assertIs(self.value("1 BETWEEN 1 AND 10"), True)
        self.assertIs(self.value("10 BETWEEN 1 AND 10"), True)

    def test_between_outside(self):
        self.assertIs(self.value("11 BETWEEN 1 AND 10"), False)
        self.assertIs(self.value("0 BETWEEN 1 AND 10"), False)

    def test_between_reversed_bounds_false(self):
        self.assertIs(self.value("5 BETWEEN 10 AND 1"), False)

    def test_between_strings(self):
        self.assertIs(self.value("'b' BETWEEN 'a' AND 'c'"), True)

    def test_between_floats(self):
        self.assertIs(self.value("1.5 BETWEEN 1 AND 2"), True)

    def test_not_between(self):
        self.assertIs(self.value("11 NOT BETWEEN 1 AND 10"), True)
        self.assertIs(self.value("5 NOT BETWEEN 1 AND 10"), False)

    def test_between_null_operand(self):
        self.assertNull("NULL BETWEEN 1 AND 2")

    def test_between_null_low_bound_but_high_fails(self):
        # NULL <= 5 AND 5 <= 1 -> NULL AND FALSE -> FALSE
        self.assertIs(self.value("5 BETWEEN NULL AND 1"), False)

    def test_between_null_high_bound(self):
        # 1 <= 5 AND 5 <= NULL -> TRUE AND NULL -> NULL
        self.assertNull("5 BETWEEN 1 AND NULL")

    def test_not_between_null_low_bound_but_high_fails(self):
        self.assertIs(self.value("5 NOT BETWEEN NULL AND 1"), True)

    def test_between_number_vs_string_is_error(self):
        self.assertExprError("5 BETWEEN 'a' AND 'z'")

    def test_between_where(self):
        self.assertRows("SELECT ID FROM products WHERE Qty BETWEEN 3 AND 5",
                        [(1,), (3,)])

    def test_not_between_where(self):
        self.assertRows(
            "SELECT ID FROM products WHERE Qty NOT BETWEEN 3 AND 5",
            [(4,), (5,)])


class TestLike(MiniSQLTestCase):
    def check(self, cases):
        for expr, expected in cases.items():
            with self.subTest(expr=expr):
                self.assertIs(self.value(expr), expected)

    def test_percent(self):
        self.check({
            "'abc' LIKE 'a%'": True,
            "'abc' LIKE '%c'": True,
            "'abc' LIKE '%b%'": True,
            "'abc' LIKE 'a%c'": True,
            "'ac' LIKE 'a%c'": True,
            "'abc' LIKE '%'": True,
            "'' LIKE '%'": True,
            "'abc' LIKE 'b%'": False,
            "'abc' LIKE '%%'": True,
        })

    def test_underscore(self):
        self.check({
            "'abc' LIKE 'a_c'": True,
            "'abc' LIKE '___'": True,
            "'abc' LIKE '__'": False,
            "'abc' LIKE 'a_'": False,
            "'ac' LIKE 'a_c'": False,
            "'abc' LIKE '_%'": True,
            "'' LIKE '_'": False,
        })

    def test_whole_string_match(self):
        self.check({
            "'abc' LIKE 'b'": False,
            "'abc' LIKE 'ab'": False,
            "'abc' LIKE 'bc'": False,
            "'abc' LIKE 'abc'": True,
            "'abcabc' LIKE 'abc'": False,
        })

    def test_case_sensitive(self):
        self.check({
            "'abc' LIKE 'A%'": False,
            "'ABC' LIKE 'abc'": False,
            "'ABC' LIKE 'A_C'": True,
        })

    def test_regex_metacharacters_are_literal(self):
        self.check({
            "'a.c' LIKE 'a.c'": True,
            "'abc' LIKE 'a.c'": False,
            "'a+b' LIKE 'a+b'": True,
            "'aab' LIKE 'a+b'": False,
            "'a*' LIKE 'a*'": True,
            "'aaa' LIKE 'a*'": False,
            "'(x)' LIKE '(x)'": True,
            "'[ab]' LIKE '[ab]'": True,
            "'a' LIKE '[ab]'": False,
            "'a?' LIKE 'a?'": True,
            "'a' LIKE 'a?'": False,
            "'^a$' LIKE '^a$'": True,
            "'a' LIKE '^a$'": False,
            "'a|b' LIKE 'a|b'": True,
            "'a' LIKE 'a|b'": False,
            "'a\\b' LIKE 'a\\b'": True,
            "'{1}' LIKE '{1}'": True,
            "'x.y.z' LIKE '%.%'": True,
            "'xyz' LIKE '%.%'": False,
        })

    def test_not_like(self):
        self.check({
            "'abc' NOT LIKE 'a%'": False,
            "'abc' NOT LIKE 'x%'": True,
        })

    def test_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name LIKE 'w%'",
                        [(1,)])
        self.assertRows("SELECT ID FROM products WHERE Name LIKE '%dg%'",
                        [(2,)])

    def test_not_like_where(self):
        self.assertRows("SELECT ID FROM products WHERE Name NOT LIKE '%g%'",
                        [(1,), (4,), (5,)])

    def test_like_pattern_expression(self):
        self.assertIs(self.value("'abc' LIKE 'a' || '%'"), True)


class TestScalarFunctions(MiniSQLTestCase):
    def test_lower_upper(self):
        self.assertValue("LOWER('AbC')", "abc")
        self.assertValue("UPPER('AbC')", "ABC")

    def test_length(self):
        self.assertValue("LENGTH('abc')", 3)
        self.assertValue("LENGTH('')", 0)

    def test_abs(self):
        self.assertEqual(self.value("ABS(-3)"), 3)
        self.assertEqual(self.value("ABS(3)"), 3)
        self.assertEqual(self.value("ABS(-2.5)"), 2.5)

    def test_round_halves_away_from_zero_to_int(self):
        self.assertValue("ROUND(2.5)", 3)
        self.assertValue("ROUND(-2.5)", -3)
        self.assertValue("ROUND(0.5)", 1)
        self.assertValue("ROUND(-0.5)", -1)
        self.assertValue("ROUND(1.5)", 2)
        self.assertValue("ROUND(3.5)", 4)

    def test_round_non_half(self):
        self.assertValue("ROUND(2.4)", 2)
        self.assertValue("ROUND(2.6)", 3)
        self.assertValue("ROUND(-2.6)", -3)

    def test_round_int_gives_int(self):
        self.assertValue("ROUND(7)", 7)

    def test_round_places_gives_float(self):
        self.assertValue("ROUND(3.14159, 2)", 3.14)
        self.assertValue("ROUND(2, 1)", 2.0)

    def test_round_places_halves_away_from_zero(self):
        # 0.125, 1.25 and 0.375 are exact in binary, so these are true halves.
        self.assertValue("ROUND(0.125, 2)", 0.13)
        self.assertValue("ROUND(-0.125, 2)", -0.13)
        self.assertValue("ROUND(1.25, 1)", 1.3)
        self.assertValue("ROUND(0.375, 2)", 0.38)

    def test_round_zero_places_gives_float(self):
        self.assertValue("ROUND(2.5, 0)", 3.0)

    def test_round_column(self):
        self.assertRows('SELECT ROUND("Unit Price") FROM products '
                        "WHERE ID IN (1, 5)", [(9,), (-2,)])

    def test_coalesce(self):
        self.assertValue("COALESCE(NULL, 2, 3)", 2)
        self.assertValue("COALESCE(1, NULL)", 1)
        self.assertValue("COALESCE(NULL, NULL, 'x')", "x")
        self.assertValue("COALESCE('only')", "only")

    def test_coalesce_all_null(self):
        self.assertNull("COALESCE(NULL, NULL)")

    def test_coalesce_column(self):
        self.assertRows("SELECT COALESCE(Qty, -1) FROM products "
                        "WHERE ID <= 2", [(3,), (-1,)])

    def test_nested_functions(self):
        self.assertValue("UPPER(LOWER('AbC') || 'd')", "ABCD")
        self.assertValue("LENGTH(COALESCE(NULL, 'abcd'))", 4)

    def test_function_on_column(self):
        self.assertRows("SELECT UPPER(Name), LENGTH(Name) FROM products "
                        "WHERE ID = 4", [("DOOHICKEY", 9)])

    def test_unknown_function_is_error(self):
        self.assertExprError("FOO(1)")
        self.assertExprError("SQRT(4)")

    def test_unknown_function_on_empty_table_is_error(self):
        # Interpretation: unknown functions are rejected even with no rows.
        self.assertQueryError("SELECT FOO(x) FROM empty")

    def test_wrong_arity_is_error(self):
        for expr in ["LOWER()", "LOWER('a', 'b')", "UPPER()",
                     "LENGTH('a', 'b')", "ABS()", "ABS(1, 2)", "ROUND()",
                     "ROUND(1, 2, 3)"]:
            with self.subTest(expr=expr):
                self.assertExprError(expr)


